def solve(w1,b1,w2,b2):
    class Linear(t.nn.Module):
        def __init__(self,w,b):
            super().__init__()
            self.weight=t.nn.Parameter(w.clone())
            self.bias=t.nn.Parameter(b.clone())
        def forward(self,x):
            return x@self.weight.T+self.bias
    class MLP(t.nn.Module):
        def __init__(self):
            super().__init__()
            self.first=Linear(w1,b1)
            self.second=Linear(w2,b2)
        def forward(self,x):
            flat=x.reshape(x.shape[0],-1)
            return self.second(self.first(flat).clamp(min=0))
    return MLP()

